// regression/vcs-infra-graph.test.ts — pin sigmashake-vcs's nodes + edges in
// the generated infrastructure graph that the cloud Worker serves at
// /api/workspace/infrastructure (local-only on cloud, but the JSON ships as
// part of the bundle and the desktop runtime reads it).
//
// The graph is regenerated by `bun run src/build-infrastructure.ts` from each
// sibling project's wrangler config; this test asserts VCS's wiring survives
// regen so an edit to sigmashake-vcs/wrangler.toml that breaks the contract
// (e.g. dropping VCS_ROOM, renaming the DO class, swapping the route) fails
// here instead of silently breaking the workspace service map.

import { describe, expect, it } from "vitest";

import { INFRASTRUCTURE_GRAPH } from "../../src/infrastructure.generated";

describe("sigmashake-vcs in the infrastructure graph", () => {
  const slug = "sigmashake-vcs";
  const worker = INFRASTRUCTURE_GRAPH.nodes.find((n) => n.id === `worker:${slug}`);
  const edgesFromWorker = INFRASTRUCTURE_GRAPH.edges.filter((e) => e.from === `worker:${slug}`);
  const allNodeIds = new Set(INFRASTRUCTURE_GRAPH.nodes.map((n) => n.id));

  it("has a worker node", () => {
    expect(worker, `worker:${slug} missing from infrastructure graph`).toBeDefined();
    expect(worker?.kind).toBe("worker");
    expect(worker?.slug).toBe(slug);
    expect(worker?.hint).toMatch(/Vibe Coder Sim/i);
  });

  it("owns the VcsRoom Durable Object", () => {
    const doId = `do:${slug}:VcsRoom`;
    expect(allNodeIds.has(doId), `${doId} node missing`).toBe(true);
    const doEdge = edgesFromWorker.find((e) => e.to === doId);
    expect(doEdge, `worker→${doId} edge missing`).toBeDefined();
    expect(doEdge?.kind).toBe("owns");
    expect(doEdge?.label).toBe("VCS_ROOM");
  });

  it("owns the static assets binding", () => {
    const assetsId = `assets:${slug}`;
    expect(allNodeIds.has(assetsId), `${assetsId} node missing`).toBe(true);
    const assetsEdge = edgesFromWorker.find((e) => e.to === assetsId);
    expect(assetsEdge?.kind).toBe("owns");
    expect(assetsEdge?.label).toBe("ASSETS");
  });

  it("routes vcs.sigmashake.com to itself via a custom_domain", () => {
    const routeEdge = edgesFromWorker.find(
      (e) => e.kind === "route" && e.to === "domain:vcs.sigmashake.com",
    );
    expect(routeEdge, "vcs.sigmashake.com route edge missing").toBeDefined();
    expect(allNodeIds.has("domain:vcs.sigmashake.com")).toBe(true);
  });

  it("binds the shared SESSIONS KV namespace (cookie auth)", () => {
    // The session_id cookie is signed by sigmashake-accounts; VCS reads it
    // out of the shared KV namespace. The ID is the namespace's KV id; pin
    // by edge label = binding name (SESSIONS) rather than the opaque id.
    const kvEdge = edgesFromWorker.find(
      (e) => e.kind === "binding" && e.label === "SESSIONS" && e.to.startsWith("kv:"),
    );
    expect(kvEdge, "SESSIONS KV binding edge missing").toBeDefined();
  });

  it("reads production secrets via the sigmashake-vault service binding", () => {
    // sigmashake-vcs migrated off direct [[secrets_store_secrets]] bindings to
    // a runtime vault read via the VAULT service binding (ENCRYPTION_KEY and
    // VCS_HMAC_KEY are fetched from sigmashake-vault on first use). The infra
    // graph emits this as a `service` edge.
    const vaultEdge = edgesFromWorker.find(
      (e) => e.kind === "service" && e.to === "worker:sigmashake-vault",
    );
    expect(vaultEdge, "VAULT service binding to sigmashake-vault is missing").toBeDefined();
  });

  it("forwards tail events to sigmashake-alerts", () => {
    const tailEdge = edgesFromWorker.find(
      (e) => e.kind === "tail" && e.to === "worker:sigmashake-alerts",
    );
    expect(tailEdge, "tail consumer wiring to sigmashake-alerts missing").toBeDefined();
  });

  it("has no dangling edges — every target is a real node", () => {
    for (const edge of edgesFromWorker) {
      expect(allNodeIds.has(edge.to), `dangling edge ${edge.from}→${edge.to}`).toBe(true);
    }
  });
});
